import{_ as e,c as t,o as i,j as s,at as c,t as r}from"./chunks/framework.BlwsHpGA.js";const b=JSON.parse('{"title":"BEUI를 위한 여정","description":"","frontmatter":{"layout":"doc","title":"BEUI를 위한 여정","lastUpdated":true,"editLink":true,"navbar":true,"sidebar":false,"aside":false,"outline":"deep","next":false},"headers":[],"relativePath":"beui/index.md","filePath":"beui/index.md"}'),v={name:"beui/index.md"};function n(d,a,o,l,f,u){return i(),t("div",null,[s("h1",null,r(d.$frontmatter.title),1),a[0]||(a[0]=c('<h2 id="" tabindex="-1" data-v-cd163f40><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;" data-v-cd163f40>​</a></h2><p data-v-cd163f40>처음 큰 규모의 프로젝트를 담당했을때 프로젝트의 각 서비스마다 제각각 구현된 컴포넌트들과 외부 라이브러리에 의존한 화면들은 커스터마이징과 성능 모두에서 한계를 드러내고 있었습니다. 새로운 요구사항이 생길 때마다 비슷한 기능을 다시 만들거나, 공용으로 쓰이던 코드에 서비스별 분기가 점점 더 많이 달라붙는 상황을 여러 차례 경험했습니다. 그런 상황을 그대로 둘 수 없었습니다.</p><p data-v-cd163f40>새로운 방식이 필요했습니다.</p><p data-v-cd163f40>그래서 UI 인프라를 위한 여정을 시작하기로 했습니다. 흩어진 컴포넌트를 모으는것 부터 시작하여 모듈 경량화, 디자인 시스템, 프레임워크 확장을 거쳤고, 이제는 AI 기반 스타일링을 통해 다음 단계의 UI 제작 방식을 실험하고 있습니다. 이제부터 그 여정을 소개합니다. --&gt;</p><h2 id="도저히-안될것같아요-대신-좀-맡아주세요" tabindex="-1" data-v-cd163f40>“도저히 안될것같아요. 대신 좀 맡아주세요” <a class="header-anchor" href="#도저히-안될것같아요-대신-좀-맡아주세요" aria-label="Permalink to &quot;“도저히 안될것같아요. 대신 좀 맡아주세요”&quot;" data-v-cd163f40>​</a></h2><p data-v-cd163f40>처음 큰 규모의 프로젝트를 맡았을때, 심폐소생 역할로 시작하게 될 줄 몰랐습니다. 레거시 코드들을 최신 프레임워크로 전환을 하는중인 프로젝트에 투입될 줄은 알았지만 이미 일정이 한참 늦어진 죽어가던(?) 자리일줄이야... 그래도 일단 배를 갈라 봤는데 ...</p><p data-v-cd163f40>가장 큰 문제는 서비스마다 제각각 구현되어 있는 중복 컴포넌트들과 외부 라이브러리에 깊이 기대고 있어서 스타일을 바꾸려면 라이브러리에 하나하나 새로운 스타일을 덮어써야 하는 라이브러리 컴포넌트들이 문제였습니다. --&gt;</p><h2 id="여정" tabindex="-1" data-v-cd163f40>여정 <a class="header-anchor" href="#여정" aria-label="Permalink to &quot;여정&quot;" data-v-cd163f40>​</a></h2><div id="journey" data-v-cd163f40><div class="be-segment border round-m" data-v-cd163f40><div class="contents" data-v-cd163f40><a href="/beui/journey1/" data-v-cd163f40><div class="title" data-v-cd163f40>여정의 시작 - 통합</div> 흩어진 사내 컴포넌트를 하나의 공용 라이브러리로 통합 </a></div></div><div class="be-segment border round-m" data-v-cd163f40><div class="contents" data-v-cd163f40><a href="/beui/journey2/" data-v-cd163f40><div class="title" data-v-cd163f40>여정에 진짜 필요한 것 - 정제</div> 무겁고 복잡해진 라이브러리를 재정비하고, 리치 컴포넌트를 공용 모듈로 분리해 경량화 </a></div></div><div class="be-segment border round-m" data-v-cd163f40><div class="contents" data-v-cd163f40><a href="/beui/journey3/" data-v-cd163f40><div class="title" data-v-cd163f40>각자 가야할 길 - 분리</div> 스타일과 기능을 분리해 디자인 시스템과 headless UI 구조를 설계 </a></div></div><div class="be-segment border round-m" data-v-cd163f40><div class="contents" data-v-cd163f40><a href="/beui/journey4/" data-v-cd163f40><div class="title" data-v-cd163f40>큰 길로 나아가기 - 확장</div> 동일한 설계 원칙을 React 환경으로 확장 </a></div></div></div>',9))])}const h=e(v,[["render",n],["__scopeId","data-v-cd163f40"]]);export{b as __pageData,h as default};
